(4831672, 699703, 20577, '<td valign="top">This might be good if it was a real drink. You can''t throw a bunch of fruit in some water and expect me to believe that this is a drink. If I tried to drink this I would probably choke to death because of all the fruit chunks... I''m no idiot!</td>', 'This might be good if it was a real drink. You can''t throw a bunch of fruit in some water and expect me to believe that this is a drink. If I tried to drink this I would probably choke to death because of all the fruit chunks... I''m no idiot!', '2008-07-17 22:02:00.000000', NULL, 1),
(4831673, 699252, 85014, '<td valign="top">I really like the colors and this photo, but my eye is lead to the middle of the photo, probably because the thing sticking out of the glass (the in focus one) is not bright enough... Nice job with the bright background!</td>', 'I really like the colors and this photo, but my eye is lead to the middle of the photo, probably because the thing sticking out of the glass (the in focus one) is not bright enough... Nice job with the bright background!', '2008-07-17 22:02:24.000000', NULL, 1),
(4831674, 699290, 85014, '<td valign="top">Its too cluttered...</td>', 'Its too cluttered...', '2008-07-17 22:02:50.000000', NULL, 1),
(4831678, 699635, 85014, '<td valign="top">I think the glass is too close to the center of the photo not to be centered...</td>', 'I think the glass is too close to the center of the photo not to be centered...', '2008-07-17 22:04:05.000000', NULL, 1),
(4831680, 699654, 85014, '<td valign="top">I don''t think that is a legal border for basic editing... nice job with the lighting</td>', 'I don''t think that is a legal border for basic editing... nice job with the lighting', '2008-07-17 22:05:02.000000', NULL, 1),
(4831682, 699464, 85014, '<td valign="top">Nice and simple...</td>', 'Nice and simple...', '2008-07-17 22:05:19.000000', NULL, 1),
