(4831965, 699655, 45475, '<td valign="top">Lovely charm to this, great idea.</td>', 'Lovely charm to this, great idea.', '2008-07-18 01:22:14.000000', NULL, 1),
(4831969, 699701, 45475, '<td valign="top">Looks like a glass sculpture, it''s so neat and smooth.</td>', 'Looks like a glass sculpture, it''s so neat and smooth.', '2008-07-18 01:23:21.000000', NULL, 1),
(4831971, 697667, 45475, '<td valign="top">Looks like the makings of one excellent drink. Nice colours, well done.</td>', 'Looks like the makings of one excellent drink. Nice colours, well done.', '2008-07-18 01:24:26.000000', NULL, 1),
(4831973, 699484, 45475, '<td valign="top">I''m gaining weight just looking at this... oh gawd that cream looks so delicious... good work!</td>', 'I''m gaining weight just looking at this... oh gawd that cream looks so delicious... good work!', '2008-07-18 01:25:33.000000', NULL, 1),
