(4832338, 698281, 40797, '<td valign="top">Cool!</td>', 'Cool!', '2008-07-18 12:06:43.000000', NULL, 1),
(4832340, 697758, 40797, '<td valign="top">Nice Splash!</td>', 'Nice Splash!', '2008-07-18 12:07:34.000000', NULL, 1),
(4832346, 699052, 96569, '<td valign="top">wow!!!!</td>', 'wow!!!!', '2008-07-18 12:16:53.000000', NULL, 1),
(4832349, 698667, 39825, '<td valign="top">shocking picture at the first moment!!! but I''m glad you didn''t REALLY destroy the lens. ;-)</td>', 'shocking picture at the first moment!!! but I''m glad you didn''t REALLY destroy the lens. ;-)', '2008-07-18 12:20:23.000000', NULL, 1),
(4832373, 699655, 82534, '<td valign="top">Very cool idea here and I love the chair and flowers.  I do wish the beverage was a little bigger to highlight it a bit more.</td>', 'Very cool idea here and I love the chair and flowers.  I do wish the beverage was a little bigger to highlight it a bit more.', '2008-07-18 12:40:22.000000', NULL, 1),
(4832374, 699428, 82534, '<td valign="top">To me, the lighting looks a bit dull on the bananas.  Otherwise, nice shot!</td>', 'To me, the lighting looks a bit dull on the bananas.  Otherwise, nice shot!', '2008-07-18 12:41:40.000000', NULL, 1),
(4832376, 698738, 82534, '<td valign="top">I really like the shallow DOF here, but unfortunately, the lime seems a bit out of focus.  Perhaps slightly deeper DOF would keep the lime and focus and still offer the pleasing background?</td>', 'I really like the shallow DOF here, but unfortunately, the lime seems a bit out of focus.  Perhaps slightly deeper DOF would keep the lime and focus and still offer the pleasing background?', '2008-07-18 12:42:42.000000', NULL, 1),
