INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4834043, 698768, 90474, '<td valign="top">I would have like the shot more with greater DOF</td>', 'I would have like the shot more with greater DOF', '2008-07-19 16:19:09.000000', NULL, 1),
(4834053, 699701, 90559, '<td valign="top">Very nice and abstract.</td>', 'Very nice and abstract.', '2008-07-19 16:35:18.000000', NULL, 1),
(4834054, 699682, 90559, '<td valign="top">Nice colors and this gives me a summer feeling just by looking at it.</td>', 'Nice colors and this gives me a summer feeling just by looking at it.', '2008-07-19 16:35:20.000000', NULL, 1),
(4834055, 699700, 76335, '<td valign="top">Lacks the sharpness and contrast to make an image like this "pop." It''s composed well and I think you''re close -- I give you credit for even trying.</td>', 'Lacks the sharpness and contrast to make an image like this "pop." It''s composed well and I think you''re close -- I give you credit for even trying.', '2008-07-19 16:35:45.000000', NULL, 1),
(4834057, 698402, 76335, '<td valign="top">I like the warm colors and the appealing reds. A nicer still life than a beverage image.</td>', 'I like the warm colors and the appealing reds. A nicer still life than a beverage image.', '2008-07-19 16:36:51.000000', NULL, 1),
(4834063, 698320, 76335, '<td valign="top">What''ll you have to drink, Mynz? Mynz?! Answer me!!!</td>', 'What''ll you have to drink, Mynz? Mynz?! Answer me!!!', '2008-07-19 16:39:56.000000', NULL, 1),
